'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={food:'吃饭',water:'饮水',litter:'如厕',rest:'休息',play:'玩耍',interaction:'互动',vomit:'疑似呕吐',device_use:'设备使用',camera_observation:'画面观察',source_observation:'设备观察'};
const truthLabels={reported:'来源记录',suspected:'疑似',confirmed:'已确认发生',rejected:'已否定'};
let home=null,page='home',day='',cursor=null,feed=[],detail=null,skip=new Set(),toastTimer,formDirty=false,captureInProgress=false;
const stamp=t=>t?new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'尚未同步';
const clock=t=>t?new Date(t).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hour12:false}):'—';
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
async function api(path,body){const r=await fetch(path,{headers:body?{'Content-Type':'application/json'}:{},method:body?'POST':'GET',body:body?JSON.stringify(body):undefined});const j=await r.json();if(!r.ok)throw new Error(j.error||'操作未完成');return j}
let reportView='cats';
let feedLocation='all', feedLoading=false, feedError='', homeRequest=0;
let storageSnapshot=null, storageLoading=false;
let photoDraft=null, photoBusy=false, photoSession=0, profileSaving=false;
function avatarUrl(c){return c.photos?.avatar?.url||`/assets/cat-${c.photos?.builtin==='default'||!c.photos?'a':c.photos.builtin}.png`}
function names(e){let n=(home?.cats||[]).filter(c=>e.participants.includes(c.id)).map(c=>c.name).join('、');return n?(n+(e.partial_unknown?'、还有未知参与者':'')):(e.kind==='camera_observation'?'身份尚未核实':'还没认出是谁')}
const eventCache=new Map(), imageLoads=new Map();
function sourceOf(e){return home?.sources.find(s=>s.id===e.source_id)}
function eventLocation(e){const source=sourceOf(e);return source?.room||e.room||`来源：${source?.name||'未命名设备'}`}
function catSubject(e){const cats=(home?.cats||[]).filter(c=>(e.participants||[]).includes(c.id));return cats.length?cats.map(c=>c.name).join('、')+(e.partial_unknown?'和另一只小猫':''):'小猫'}
function title(e){const subject=catSubject(e);let text;if(e.kind==='source_observation'){text=({pet:`${subject}来过了`,pet_detect:`${subject}来过了`,move:'好像有小猫路过了',pump_work:'饮水机出水了'})[e.original?.category]||'有了新的动静'}else if(e.kind==='camera_observation'){text=`镜头里看到了${subject}`}else if(e.kind==='device_use'){text=e.original?.category==='feed'?'食盆添粮了':'设备工作了'}else if(e.kind==='vomit'){text=e.truth==='confirmed'?`${subject}吐了`:`${subject}可能吐了`}else{const action={food:'吃饭了',water:'喝水了',litter:'上厕所了',rest:'休息了',play:'玩耍了',interaction:'一起玩了'}[e.kind];text=action?`${subject}${e.truth==='suspected'?'可能':''}${action}`:'有了一条新记录'}return e.truth==='rejected'?`已否定 · ${text}`:text}
function localImage(e){return e.evidence?.find(m=>m.kind==='image')}
function mediaMessage(e,kind){if(e.evidence?.some(m=>m.kind===kind))return '';const state=e.media?.[kind];if(state==='expired')return '视频已过期，文字记录仍保留。';if(kind==='image'&&imageLoads.get(e.id)?.state==='loading')return '正在读取云端截图…';if(kind==='image'&&imageLoads.get(e.id)?.state==='failed')return `截图读取失败：${imageLoads.get(e.id).error}`;if(state==='remote_unverified')return `${kind==='image'?'截图':'视频'}在云端，尚未保存到本机。`;return kind==='image'?'最近读取未发现截图，云端可能稍后补齐。':'最近读取未发现视频，云端可能稍后补齐。'}
function thumbnail(e){const m=localImage(e);return m?`<img src="/api/media/${esc(m.id)}" alt="这条记录的截图" loading="lazy">`:`<span>${esc(e.media?.image==='remote_unverified'?'截图待读取':withoutCamera(sourceOf(e))?'文字记录':'尚无截图')}</span>`}
function row(e){eventCache.set(e.id,e);return `<button class="row" data-event="${esc(e.id)}"><time class="time">${esc(clock(e.occurred_at))}</time><span class="event-thumb" data-thumbnail="${esc(e.id)}">${thumbnail(e)}</span><span class="row-copy"><strong>${esc(title(e))}</strong><small>${esc(eventLocation(e))}${e.kind==='camera_observation'?' · 活动尚未核实':''}${e.mode==='fixture'?' · 测试数据':''}</small><small>${esc(names(e))}</small></span><span class="tag">${e.truth==='rejected'?'已否定':e.partial_unknown?'身份待核对':'已归属'}</span></button>`}
function evidencePanel(e){
 const image=localImage(e),video=e.evidence.find(m=>m.kind==='video');
 if(withoutCamera(sourceOf(e)))return '<section class="event-text-record"><strong>文字记录</strong><p class="quiet">本设备无摄像头，可按时间和设备报告核对。</p></section>';
 const imageLink=image?`<a class="event-original" href="/api/media/${esc(image.id)}" target="_blank" rel="noopener">查看原图</a>`:'';
 return `<section class="evidence event-media">${video?`<video controls playsinline preload="metadata" src="/api/media/${esc(video.id)}"></video>`:image?`<a class="event-image" href="/api/media/${esc(image.id)}" target="_blank" rel="noopener"><img src="/api/media/${esc(image.id)}" alt="原事件截图，点击放大"></a>`:`<div class="event-media-empty"><p class="quiet" role="status">${esc(mediaMessage(e,'image'))}</p>${e.mode==='petkit'?`<button data-petkit-image="${esc(e.id)}" ${imageLoads.get(e.id)?.state==='loading'?'disabled':''}>${imageLoads.get(e.id)?.state==='failed'?'重试读取截图':e.media.image==='remote_unverified'?'读取截图':'检查云端截图'}</button>`:''}</div>`}<div class="event-media-tools">${e.mode==='petkit'&&e.media.video==='remote_unverified'&&!video?`<button data-petkit-video="${esc(e.id)}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" aria-hidden="true"><path d="m9 5 10 7-10 7Z"></path></svg>读取并播放视频</button><span class="quiet">云端视频</span>`:!video&&(!image||e.media.video==='expired')?`<span class="quiet">${esc(mediaMessage(e,'video'))}</span>`:''}${!video?imageLink:''}</div>${video&&image?`<details class="event-screenshot"><summary>查看截图</summary><a href="/api/media/${esc(image.id)}" target="_blank" rel="noopener"><img src="/api/media/${esc(image.id)}" alt="原事件截图，点击放大">查看原图</a></details>`:''}</section>`;
}
function updateEvidence(e){eventCache.set(e.id,e);feed=feed.map(x=>x.id===e.id?e:x);document.querySelectorAll('[data-thumbnail]').forEach(el=>{if(el.dataset.thumbnail===e.id){el.innerHTML=thumbnail(e);if(!localImage(e))el.textContent=imageLoads.get(e.id)?.state==='failed'?'读取失败':imageLoads.get(e.id)?.state==='loading'?'读取中…':e.media?.image==='remote_unverified'?'截图待读取':withoutCamera(sourceOf(e))?'文字记录':'尚无截图'}});if(detail?.id===e.id){detail=e;const el=$('#event-evidence');if(el)el.innerHTML=evidencePanel(e)}}
async function ensureImage(e,retry=false){if(localImage(e)||e.mode!=='petkit'||(!retry&&e.media?.image!=='remote_unverified'))return;const previous=imageLoads.get(e.id);if(previous?.state==='loading')return previous.promise;if(previous&&!retry)return;const source=sourceOf(e);if(!home?.runtime.recording||source?.recording_enabled===false||source?.status!=='online')return;const load={state:'loading'};imageLoads.set(e.id,load);updateEvidence(e);load.promise=(async()=>{try{const job=await api(`/api/sources/${encodeURIComponent(e.source_id)}/petkit-jobs`,{action:'image',argument:e.id});let complete=false;for(let i=0;i<60;i++){const result=await api('/api/petkit-jobs/'+encodeURIComponent(job.id));if(result.state==='failed')throw new Error(result.error||'云端读取未完成');if(result.state==='completed'){complete=true;break}await new Promise(r=>setTimeout(r,2000))}if(!complete)throw new Error('读取超时，稍后可重试');const current=await api('/api/events/'+encodeURIComponent(e.id));if(!localImage(current))throw new Error('读取完成但未获得截图');load.state='completed';updateEvidence(current)}catch(error){load.state='failed';load.error=error.message;updateEvidence(eventCache.get(e.id)||e)}})();return load.promise}
let thumbnailObserver=null, thumbnailQueue=[], thumbnailBusy=false;
function observeThumbnails(){if(!('IntersectionObserver' in window))return;thumbnailObserver?.disconnect();thumbnailObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){thumbnailObserver.unobserve(entry.target);const e=eventCache.get(entry.target.dataset.thumbnail);if(e&&!localImage(e)&&e.media?.image==='remote_unverified'&&!imageLoads.has(e.id)){thumbnailQueue.push(e.id);void drainThumbnails()}}},{rootMargin:'100px'});document.querySelectorAll('[data-thumbnail]').forEach(el=>thumbnailObserver.observe(el))}
async function drainThumbnails(){if(thumbnailBusy)return;thumbnailBusy=true;try{while(thumbnailQueue.length){const id=thumbnailQueue.shift();if(![...document.querySelectorAll('[data-thumbnail]')].some(el=>el.dataset.thumbnail===id))continue;await ensureImage(eventCache.get(id))}}finally{thumbnailBusy=false}}
function sourceStatus(s){if(s.petkit_kind==='fountain'&&s.status==='online'){if(!s.heartbeat||Date.now()-new Date(s.heartbeat).getTime()>120000)return '后台未响应';return '状态已读取'}if(s.mode==='camera'&&s.status==='online'&&(!s.heartbeat||Date.now()-new Date(s.heartbeat).getTime()>15000))return '后台未响应';return ({online:'采集中',offline:'连接中断',paused:'已暂停',stopped:'后台已停止',fixture:'测试来源',unverified:'待验证',blocked:'账号读取暂不可用'})[s.status]||s.status}
function catCards(){return home.cats.map((c,i)=>`<button class="cat" data-cat="${esc(c.id)}"><img src="${esc(avatarUrl(c))}" alt=""><strong>${esc(c.name)}</strong><div class="metrics">${['food','water','litter'].map(k=>`<span>${labels[k]}<b>${c.counts[k]??'—'}</b></span>`).join('')}</div><div class="cat-location">${c.last_observation?`${esc(c.last_observation.room||'位置未提供')}<br>${esc(clock(c.last_observation.occurred_at))} 最近观察`:'尚无已归属观察'}</div></button>`).join('')}
function withoutCamera(s){return ['d4s','t4','ctw3'].includes(s?.petkit_model)}
function sourceReportNote(s){return s.petkit_kind==='litter'?'猫砂盆使用报告和每日汇总；清洁动作不计入使用次数。':s.petkit_kind==='fountain_basic'?'出水工作记录，不计入饮水次数；蓝牙设备数据可能晚于当前时间。':'设备报告进食与投粮；投粮不等于进食，不分配到具体猫咪。'}
function reportIcon(key){const shapes={food:'<path d="M4 11h16l-2 8H6Z"></path><path d="M8 4v3m4-4v4m4-3v3"></path>',water:'<path d="M12 3S5 10 5 14a7 7 0 0 0 14 0c0-4-7-11-7-11Z"></path><path d="M9 14a3 3 0 0 0 3 3"></path>',litter:'<path d="M3 10h18l-2 10H5Z"></path><path d="M6 10V5h12v5M8 15h8"></path>',device_use:'<path d="m6 16 4-4 4 4-4 4Z"></path><path d="m13 8 4-4 4 4-4 4Z"></path><path d="m3 7 3-3 3 3-3 3Z"></path>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[key]||''}</svg>`}
function deviceReportCards(){const r=home.device_reports;if(!r)return '';const counts=r.counts||{};return `<section class="section device-reports"><div class="report-title"><h2>全家的吃喝日常</h2><button class="report-help" data-action="report-help" aria-label="查看吃喝日常统计说明"><svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"></circle><path d="M12 11v6"></path><path d="M12 7h.01"></path></svg></button></div><div class="report-counts">${[['food','吃饭'],['water','喝水'],['litter','如厕'],['device_use','添粮']].map(([key,label])=>`<div class="metric-${key}"><div class="report-metric-label"><span class="report-metric-icon">${reportIcon(key)}</span><small>${label}</small></div><strong>${counts[key]||'—'}</strong></div>`).join('')}</div></section>`}
function deviceCards(){return (home.device_reports?.devices||[]).map(d=>{const source=home.sources.find(s=>s.id===d.source_id);const type=d.model==='t4'?'猫砂盆':d.model==='ctw3'||d.model==='w7h'?'饮水机':'喂食器';const keys=d.model==='t4'?[['litter','使用']]:d.model==='ctw3'?[['pump_work','出水工作']]:d.model==='w7h'?[['water','饮水']]:[['food','进食'],['device_use','投粮']];return `<article class="device-card"><div class="device-card-type"><span>${type}</span><span class="device-card-status"><i class="dot ${d.status==='online'?'online':''}"></i>${d.status==='online'?'已连接':esc(source?sourceStatus(source):'待同步')}</span></div><strong class="device-card-name">${esc(d.name)}</strong><div class="device-card-metrics">${keys.map(([key,label])=>`<div><span>${label}</span><b>${d.counts[key]||'—'}</b></div>`).join('')}</div><details id="device-card-${esc(d.source_id)}" ${document.getElementById('device-card-'+d.source_id)?.open?'open':''}><summary>详情</summary><p>最近读取 ${esc(stamp(d.updated_at))}${source?.room?`<br>位置：${esc(source.room)}`:''}${d.daily_summary?`<br>设备日汇总：使用 ${esc(d.daily_summary.times??'—')} 次（与逐次记录分别保留）`:''}${d.model==='ctw3'?'<br>出水工作不等于一次喝水。':''}</p></details></article>`}).join('')||'<p class="quiet">尚无设备报告。</p>'}
function reportOverview(){return `<section class="section report-overview"><div class="report-view-switch" role="group" aria-label="报告查看方式">${[['cats','按猫咪看'],['devices','按设备看']].map(([value,label])=>`<button data-report-view="${value}" aria-pressed="${reportView===value}">${label}</button>`).join('')}</div><div id="report-view-content">${reportView==='cats'?`${home.cats.length?`<div class="cats">${catCards()}</div>`:`<p class="empty">先认识家里的小猫。默认头像就能开始。</p><button class="primary" data-action="create-family">建立汤圆、飞饼、话唠资料</button><button data-action="add-cat">单独添加一只</button>`}`:`<div class="device-report-list">${deviceCards()}</div>`}</div></section>`}
function recordingNotice(){
 if(!home.runtime.recording)return '记录已暂停';
 const inactive=home.sources.filter(s=>s.recording_enabled===false||!['采集中','状态已读取','测试来源'].includes(sourceStatus(s)));
 if(!inactive.length)return '';
 const paused=inactive.filter(s=>s.recording_enabled===false||s.status==='paused').length;
 return [inactive.length>paused?`${inactive.length-paused} 台设备未连接`:'',paused?`${paused} 台已暂停`:''].filter(Boolean).join(' · ');
}
function dailyHelpButton(){return '<button class="report-help daily-help" data-action="daily-help" aria-label="查看小日常记录说明"><svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="9"></circle><path d="M12 11v6M12 7h.01"></path></svg></button>'}
function showDailyHelp(){detail=null;formDirty=false;$('#detail').innerHTML='<div class="dialog-head"><h2 id="dialog-title">小日常 · 记录说明</h2><button class="close" data-action="close" aria-label="关闭说明">×</button></div><p class="quiet">来过不一定是在吃喝，同一只猫停留时也可能留下多条记录。</p><p class="quiet">画面可用并不代表已经识别活动。记录空白也不代表猫咪没有活动。</p>';$('#detail').showModal()}
function recordingNoticeButton(){const text=recordingNotice();return text?`<button class="recording-notice" data-action="device-status" aria-label="${esc(text)}，查看采集状态">${esc(text)}</button>`:''}
function dailyFeedQuery(extra={}){
 const params=new URLSearchParams();if(day)params.set('date',day);
 if(feedLocation==='unlocated')params.set('unlocated','true');
 else if(feedLocation.startsWith('room:'))params.set('room',feedLocation.slice(5));
 for(const [key,value] of Object.entries(extra))params.set(key,value);
 return '/api/home?'+params;
}
function dailyLocationFilters(){
 const locations=home.feed_locations||[...new Set(home.sources.map(s=>s.room||null))].map(room=>({room}));
 const options=[{value:'all',label:'全部'},...locations.map(l=>({value:l.room===null?'unlocated':'room:'+l.room,label:l.room||'位置待填写'}))];
 if(!options.some(o=>o.value===feedLocation))options.push({value:feedLocation,label:feedLocation==='unlocated'?'位置待填写':feedLocation.slice(5)});
 return `<div class="daily-location-filters" id="daily-location-filters" role="group" aria-label="按位置筛选小日常">${options.map(o=>`<button data-feed-location="${esc(o.value)}" aria-pressed="${o.value===feedLocation}">${esc(o.label)}</button>`).join('')}</div>`;
}
function dailyFeedRows(){
 if(feedLoading)return '<p class="empty" role="status">正在读取日常记录…</p>';
 if(feedError)return `<p class="error" role="alert">${esc(feedError)}</p>`;
 if(feed.length)return feed.map(row).join('');
 return `<p class="empty" role="status">${feedLocation==='all'?'今天还没有日常记录。':feedLocation==='unlocated'?'今天没有位置待填写的记录。':esc(feedLocation.slice(5))+'今天还没有日常记录。'}</p>`;
}
async function selectFeedLocation(value){
 if(value===feedLocation)return;
 const scroll=window.scrollY, strip=$('#daily-location-filters').scrollLeft;
 feedLocation=value;feedLoading=true;feedError='';feed=[];cursor=null;renderHome();
 $('#daily-location-filters').scrollLeft=strip;window.scrollTo(0,scroll);
 await refresh();
}
function reviewEntry(){return `<section class="section"><button class="review" data-action="review"><span>待认猫 <span class="review-entry-count">${home.review_count} 条</span></span><span class="review-entry-action">去核对${settingsIcon('chevron')}</span></button></section>`}
function renderHome(){$('#content').innerHTML=`<section class="summary"><div class="summary-heading"><span class="summary-mark" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6Z"></path></svg></span><h2>今天总结</h2><input class="summary-date" id="day" type="date" aria-label="查看日期" value="${home.date}"></div><p>${esc(home.summary)}</p></section>${home.alerts.length?`<section><h2>需要你看一眼</h2>${home.alerts.map(e=>`<button class="alert" data-event="${esc(e.id)}"><strong>${e.truth==='confirmed'?'已确认呕吐 · 仍待关注':'疑似呕吐 · 待核实'}</strong><small>${esc(stamp(e.occurred_at))} · ${esc(eventLocation(e))} · 查看证据 →</small></button>`).join('')}</section>`:''}${deviceReportCards()}${reportOverview()}<section class="section"><div class="section-heading daily-heading"><div class="daily-title"><h2>全家的小日常</h2>${dailyHelpButton()}${recordingNoticeButton()}</div><button data-action="history">查历史</button></div>${dailyLocationFilters()}${dailyFeedRows()}${cursor?'<button class="full" data-action="more">展开更早记录</button>':''}</section>${reviewEntry()}`}
function analysisStatus(){const labels={unconfigured:'尚未启用',unavailable:'暂不可用',running:'分析中',idle:'等待新画面',paused:'已暂停',blocked:'尚未就绪',failed:'本次分析失败',stopped:'已停止'};return `<p class="quiet">本机猫咪位置候选：${esc(labels[home.analysis?.status]||'尚未启用')}。定位不确认身份或活动；自动认猫与呕吐检测属于后续版本。</p>`}
function renderLocalization(c){const l=c.localization;if(!l||l.status!=='completed')return '';const boxes=Array.isArray(l.boxes)?l.boxes:[];const valid=Number.isFinite(l.width)&&l.width>0&&Number.isFinite(l.height)&&l.height>0;return `<section><h3>画面位置候选</h3><p class="quiet">${boxes.length?'位置框供认猫核对，不确认猫咪身份或活动。':'尚未找到可用的猫咪位置候选，不代表没有猫。'}${c.camera_candidate?(c.camera_association==='confirmed'?'画面关联已人工确认；位置框仍是模型候选。':c.camera_association==='rejected'?'画面关联已否定，不用于说明原记录。':'这是同时间摄像头候选画面，与原记录的关联仍需单独核对。'):''}</p>${valid&&boxes.length?`<div class="localization-image"><img src="/api/media/${esc(c.media_id)}" alt="猫咪位置候选画面">${boxes.filter(b=>Array.isArray(b.box)&&b.box.length===4&&b.box.every(Number.isFinite)).map(b=>`<span class="localization-box" style="left:${Math.max(0,b.box[0]/l.width*100)}%;top:${Math.max(0,b.box[1]/l.height*100)}%;width:${Math.max(0,(b.box[2]-b.box[0])/l.width*100)}%;height:${Math.max(0,(b.box[3]-b.box[1])/l.height*100)}%"></span>`).join('')}</div>`:''}</section>`}
function storageSize(value){if(!Number.isFinite(value)||value<0)return '暂不可读';if(value<1024)return `${value} B`;const units=['KiB','MiB','GiB','TiB'];let n=value/1024,i=0;while(n>=1024&&i<units.length-1){n/=1024;i++}return `${n.toFixed(1)} ${units[i]}`}
function renderStorage(){const s=storageSnapshot;if(!s)return '<p class="quiet settings-note">查看截图、视频用量与磁盘剩余空间。</p>';return `<div class="settings-storage-metrics">${[['已保存媒体',s.logical_bytes],['磁盘剩余',s.disk_free_bytes],['视频',s.kinds?.video?.bytes],['截图',s.kinds?.image?.bytes]].map(([label,value])=>`<div><small>${label}</small><strong>${esc(storageSize(value))}</strong></div>`).join('')}</div>${s.missing_count||s.unsafe_count?`<p class="error">${esc(s.missing_count||0)} 个媒体文件不可用，${esc(s.unsafe_count||0)} 个引用暂不能核对；文字记录保留。</p>`:''}<details class="settings-inner-group" id="settings-storage-policy" ${settingsOpen('settings-storage-policy')}><summary><span>保存与清理规则</span><span class="settings-chevron">${settingsIcon('chevron')}</span></summary><p class="quiet">${s.policy?.active?.enabled?'视频从保存到本机起保留48小时，每5分钟检查到期清理；启用前的视频从启用时起保留48小时。':'视频保留48小时的口径已确认，自动清理尚未启用。'}截图与文字保留，暂停采集不延长视频期限。</p><p class="quiet">用量核对于 ${esc(stamp(s.checked_at))}。只统计已登记媒体，不含数据库、参考照片、模型和备份。</p>${s.policy?.last_check?`<p class="quiet">最近清理 ${esc(stamp(s.policy.last_check.checked_at))} · 已过期 ${esc(s.expired_count||0)} 段${s.policy.last_check.failed?` · ${esc(s.policy.last_check.failed)} 段处理失败，将重试`:''}</p>`:''}</details>`}
function settingsIcon(kind){const paths={cats:'<path d="m5 10 1-7 6 4 6-4 1 7c5 10-19 10-14 0Z"></path><path d="M9 12h.01M15 12h.01m-4 3 1 1 1-1"></path>',devices:'<rect x="4" y="3" width="16" height="13" rx="2"></rect><path d="M8 21h8m-4-5v5"></path>',service:'<path d="M3 12h4l3-8 4 16 3-8h4"></path>',storage:'<ellipse cx="12" cy="5" rx="8" ry="3"></ellipse><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"></path>',edit:'<path d="m16 3 5 5-12 12-6 1 1-6Z"></path><path d="m14 5 5 5"></path>',chevron:'<path d="m9 5 7 7-7 7"></path>',add:'<path d="M12 5v14M5 12h14"></path>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[kind]||''}</svg>`}
function settingsOpen(id){return document.getElementById(id)?.open?'open':''}
function deviceMapping(){const missing=home.sources.filter(s=>!s.room).length;return `<details class="settings-card settings-group" id="settings-devices" ${settingsOpen('settings-devices')}><summary><span class="settings-category-icon">${settingsIcon('devices')}</span><span class="settings-heading-text"><strong>设备与位置</strong><small>${home.sources.length} 台设备${missing?` · ${missing} 台位置待填写`:''}</small></span><span class="settings-chevron">${settingsIcon('chevron')}</span></summary><div class="settings-group-body"><p class="quiet settings-note">维护设备名称、厂商和安装位置。</p><div class="device-mapping">${home.sources.map(s=>`<article><div><strong>${esc(s.name)}</strong><small>${esc(s.manufacturer||'厂商待填写')} · ${esc(s.room||'位置待填写')}</small></div><button class="settings-icon-button" data-edit-device="${esc(s.id)}" aria-label="编辑${esc(s.name)}的设备资料">${settingsIcon('edit')}</button></article>`).join('')||'<p class="quiet">尚未配置设备。</p>'}</div></div></details>`}
function sourceSettings(){return home.sources.map(s=>`<details class="settings-source" id="settings-source-${esc(s.id)}" ${settingsOpen('settings-source-'+s.id)}><summary><span class="settings-heading-text"><strong>${esc(s.name)}</strong><small>${esc(sourceStatus(s))}</small></span><span class="settings-chevron">${settingsIcon('chevron')}</span></summary><div class="settings-source-body"><p class="quiet">最近读取 ${esc(stamp(s.last_sync))}</p><div class="actions">${['camera','petkit'].includes(s.mode)?`<button data-source-recording="${esc(s.id)}" data-enable="${s.recording_enabled===false?'true':'false'}">${s.recording_enabled===false?'恢复此设备':'暂停此设备'}</button>`:''}${s.mode==='petkit'&&s.petkit_kind!=='fountain'?`<button data-petkit-history="${esc(s.id)}">读取所选日期记录</button>`:''}${s.mode==='camera'?`<button data-capture="${esc(s.id)}" ${sourceStatus(s)!=='采集中'?'disabled':''}>保存当前画面</button>`:''}</div><p class="quiet">${s.capabilities.video?'支持视频片段':withoutCamera(s)?'无摄像头 · 文字记录':'视频尚不可用'} · ${s.capabilities.identity?'身份能力已验证':'身份需人工核对'}</p>${s.mode==='petkit'?`<p class="quiet">${s.petkit_kind==='fountain'?'可读取逐次出现和喝水记录，尚不支持指定日期补录。':esc(sourceReportNote(s))}</p>`:''}${s.camera_relation?'<p class="quiet">摄像头已确认覆盖食盆；同时间画面关联仍需核对。</p>':''}${s.mode==='camera'?'<p class="quiet">主动保存最近约5秒画面，活动尚未核实。</p>':''}<details id="settings-gaps-${esc(s.id)}" ${settingsOpen('settings-gaps-'+s.id)}><summary>记录缺口 · ${s.gaps?.length||0}</summary>${s.gaps?.length?s.gaps.map(g=>`<p>${esc(stamp(g.start))} — ${g.end?esc(stamp(g.end)):'尚未恢复'}<br>${esc(g.reason)}</p>`).join(''):'<p>暂无已记录的缺口，不代表此前观察完整。</p>'}</details></div></details>`).join('')||'<p class="quiet">尚未配置设备。</p>'}
function editDevice(id){const s=home.sources.find(s=>s.id===id);if(!s)return;detail=null;formDirty=false;$('#detail').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">设备映射</h2><button data-action="close" aria-label="关闭编辑">×</button></div><form id="device-form" data-id="${esc(id)}" data-version="${s.profile_version||0}"><label class="field">设备名称<input name="name" required maxlength="100" value="${esc(s.name)}"></label><label class="field">设备厂商<input name="manufacturer" required maxlength="100" value="${esc(s.manufacturer)}"></label><label class="field">所属位置<input name="room" maxlength="100" placeholder="例如：客厅、阳台；不确定时留空" value="${esc(s.room)}"></label><p class="quiet">这是设备安装位置，不代表猫咪当前所在位置。</p><p id="save-error" class="error" role="alert"></p><button type="submit" class="primary">保存映射</button></form>`;if(!$('#detail').open)$('#detail').showModal();$('#device-form input').focus()}
document.addEventListener('submit',async ev=>{if(ev.target.id!=='device-form')return;ev.preventDefault();const form=ev.target,button=form.querySelector('[type=submit]');if(button.disabled)return;button.disabled=true;try{const fields=new FormData(form);await api(`/api/sources/${encodeURIComponent(form.dataset.id)}/profile`,{version:Number(form.dataset.version),name:fields.get('name'),manufacturer:fields.get('manufacturer'),room:fields.get('room')});formDirty=false;$('#detail').close();await refresh(false);toast('设备映射已保存')}catch(e){$('#save-error').textContent=e.message;button.disabled=false}});
document.addEventListener('input',ev=>{if(ev.target.closest('#device-form'))formDirty=true});
function renderSettings(){page='settings';const online=home.sources.filter(s=>['采集中','状态已读取'].includes(sourceStatus(s))).length;$('#content').innerHTML=`<div class="settings-layout"><section class="settings-card"><div class="settings-card-heading"><span class="settings-category-icon">${settingsIcon('cats')}</span><h2>猫咪资料</h2><span class="settings-count">${home.cats.length} 只</span><button class="settings-text-button" data-action="add-cat" aria-label="添加猫咪">${settingsIcon('add')}添加</button></div><div class="settings-cat-list">${home.cats.map(c=>`<button class="settings-cat" data-edit="${esc(c.id)}" aria-label="编辑${esc(c.name)}的猫咪资料"><img src="${esc(avatarUrl(c))}" alt=""><span class="settings-heading-text"><strong>${esc(c.name)}</strong><small>${esc(c.description||'头像与参考照片')}</small></span><span class="settings-chevron">${settingsIcon('chevron')}</span></button>`).join('')}${!home.cats.length?'<p class="quiet">添加猫咪，保存头像和参考照片。</p><button data-action="create-family">建立汤圆、飞饼、话唠资料</button>':''}</div></section>${deviceMapping()}<section class="settings-card"><div class="settings-card-heading"><span class="settings-category-icon">${settingsIcon('service')}</span><h2>采集服务</h2></div><div class="settings-service-state"><div><strong>${home.runtime.recording?'记录已启用':'记录已暂停'}</strong><small>${online} / ${home.sources.length} 台来源在线</small></div><button data-action="toggle" class="settings-text-button">${home.runtime.recording?'暂停记录':'恢复记录'}</button></div><details class="settings-inner-group" id="settings-sources" ${settingsOpen('settings-sources')}><summary><span>逐设备采集与补录</span><span class="settings-chevron">${settingsIcon('chevron')}</span></summary><div class="settings-date-row"><label for="day">补录日期</label><input id="day" type="date" aria-label="补录日期" value="${home.date}"></div>${sourceSettings()}</details><details class="settings-inner-group" id="settings-service-notes" ${settingsOpen('settings-service-notes')}><summary><span>采集与识别说明</span><span class="settings-chevron">${settingsIcon('chevron')}</span></summary><p class="quiet">关闭或收起页面，后台仍会继续记录。暂停会停止采集，已有资料保留。</p>${analysisStatus()}<p class="quiet">当前使用人工认猫；自动认猫、呕吐检测和外部提醒尚未启用。</p></details></section><section class="settings-card"><div class="settings-card-heading"><span class="settings-category-icon">${settingsIcon('storage')}</span><h2>本机存储</h2><button class="settings-text-button" data-action="storage" ${storageLoading?'disabled':''}>${storageLoading?'读取中…':storageSnapshot?'刷新用量':'查看用量'}</button></div><div id="storage-summary" aria-live="polite">${renderStorage()}</div></section></div>`;nav()}
function nav(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===(page==='settings'?'settings':'home')))}
async function refresh(reset=true){
 const request=++homeRequest;
 try{
  const oldScroll=window.scrollY, strip=$('#daily-location-filters')?.scrollLeft||0;
  const size=!reset?Math.max(12,Math.min(100,feed.length)):12;
  const next=await api(dailyFeedQuery({limit:size}));if(request!==homeRequest)return;
  home=next;feedLoading=false;feedError='';$('#connection').textContent='';feed=home.events;cursor=home.next_cursor;
  if(page==='home'){renderHome();$('#daily-location-filters').scrollLeft=strip}
  else if(page==='settings')renderSettings();
  observeThumbnails();nav();if(!reset)window.scrollTo(0,oldScroll);
 }catch(e){
  if(request!==homeRequest)return;
  feedLoading=false;feedError='日常记录读取失败，请稍后重试。';
  if(page==='home'&&home)renderHome();
  $('#connection').textContent='本机服务暂不可达，已保存的资料不会被清空。';toast(e.message);
 }
}
async function openEvent(id){try{detail=await api('/api/events/'+encodeURIComponent(id));renderEvent();if(!$('#detail').open)$('#detail').showModal();void ensureImage(detail)}catch(e){toast(e.message)}}
const associationLabels={unverified:'关联待核对',confirmed:'已确认关联',rejected:'已否定关联'};
function renderCandidate(c){const ready=c.state==='completed'&&c.media.length;return `<section class="evidence candidate"><h3>同时间候选画面 · ${esc(associationLabels[c.association])}</h3><p class="quiet">${esc(home.sources.find(s=>s.id===c.source_id)?.name||c.source_id)}<br>按设备报告时间取摄像头缓冲；时钟偏差尚未验证。关联核对只判断画面是否对应这条记录，不确认行为或猫咪身份。${c.requested_window?`<br>请求时段 ${esc(stamp(c.requested_window.start_at))} — ${esc(stamp(c.requested_window.end_at))}`:''}${c.state==='completed'?'':`<br>${esc(c.reason||'候选画面保存中')}`}</p>${c.media.map(m=>m.kind==='video'?`<video controls playsinline preload="metadata" src="/api/media/${esc(m.id)}"></video>`:`<a href="/api/media/${esc(m.id)}" target="_blank" rel="noopener"><img src="/api/media/${esc(m.id)}" alt="${esc(associationLabels[c.association])}的候选画面">查看候选原图</a>`).join('')}${c.video_expired?'<p class="quiet">候选视频已过期，截图及关联核对历史仍保留。</p>':''}${!c.media.length?'<p class="quiet">暂无候选媒体，暂不能核对关联。</p>':''}<div class="actions"><button data-candidate="${esc(c.source_id)}" data-association="confirmed" ${!ready||c.association==='confirmed'?'disabled':''}>确认画面关联</button><button data-candidate="${esc(c.source_id)}" data-association="rejected" ${!ready||c.association==='rejected'?'disabled':''}>否定画面关联</button><button data-candidate="${esc(c.source_id)}" data-association="undo" ${!c.association_history.length||c.association_history.at(-1).operation==='undo'?'disabled':''}>撤回最近关联核对</button></div><details><summary>关联核对历史</summary>${c.association_history.map(h=>`<p>${esc(stamp(h.created_at))} · ${h.operation==='undo'?'撤回关联核对':'人工关联核对'} · ${esc(associationLabels[h.before_association])} → ${esc(associationLabels[h.after_association])} · v${h.version}</p>`).join('')||'<p>尚无关联核对。</p>'}</details></section>`}
async function candidateReview(source,association){if(formDirty&&!confirm('放弃尚未保存的身份修改并核对画面关联？'))return;const c=detail.camera_candidates.find(c=>c.source_id===source);const buttons=[...$('#detail').querySelectorAll('button')];const disabled=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);try{detail=await api(`/api/events/${detail.id}/camera-candidates/${source}/${association==='undo'?'undo':'review'}`,{version:c.association_version,association});renderEvent();toast('画面关联已保存')}catch(e){$('#save-error').textContent=e.message;buttons.forEach((b,i)=>b.disabled=disabled[i])}}
function eventDisclosure(id,heading,body,defaultOpen=false){
 const same=$('#detail .event-detail')?.dataset.eventId===detail.id;
 const open=same&&document.getElementById(id)?document.getElementById(id).open:defaultOpen;
 return `<details class="event-disclosure" id="${id}" ${open?'open':''}><summary><span>${heading}</span><span class="event-chevron">${settingsIcon('chevron')}</span></summary><div class="event-disclosure-body">${body}</div></details>`;
}
function eventIdentity(e){
 const form=`<form id="identity-form"><div class="event-cat-options">${home.cats.map(c=>`<label class="event-cat-option"><input type="checkbox" name="participant" value="${esc(c.id)}" ${e.participants.includes(c.id)?'checked':''}><img src="${esc(avatarUrl(c))}" alt=""><span>${esc(c.name)}</span></label>`).join('')}</div><label class="check"><input type="checkbox" name="unknown" ${e.partial_unknown?'checked':''}>还有未认出的猫咪</label><button class="primary" type="submit">保存身份${page==='review'?'并下一条':''}</button><p class="quiet">只保存身份，活动仍需单独核实。</p></form>`;
 const references=`<details class="event-reference"><summary>查看认猫参考照片</summary><section class="photo-references"><p class="quiet">参考照片仅供人工核对。</p>${home.cats.map(c=>`<article><strong>${esc(c.name)}</strong><p>${esc(c.description||'暂无外观说明')}</p><div class="reference-grid">${(c.photos?.references||[]).map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener"><img src="${esc(r.url)}" alt="${esc(c.name)}的核对参照"></a>`).join('')||'<span class="quiet">尚未添加参考照片</span>'}</div></article>`).join('')}</section></details>`;
 return eventDisclosure('event-identity',`<strong>是哪只小猫？</strong><small>${esc(names(e))}</small>`,form+references,page==='review');
}
function renderEvent(){
 formDirty=false;const e=detail;
 const duration=Number.isFinite(e.original.facts?.duration)?` · ${esc(e.original.facts.duration)} 秒`:'';
 const source=sourceOf(e);
 const original=`<dl class="event-source-facts"><div><dt>设备</dt><dd>${esc(source?.name||e.source_id)}</dd></div><div><dt>厂商</dt><dd>${esc(source?.manufacturer||'尚未填写')}</dd></div><div><dt>原始类型</dt><dd>${esc(labels[e.original.kind]||e.original.kind||labels[e.kind])}</dd></div></dl><p class="quiet">${esc(e.original.note||'原始来源报告已保留。')}</p>${e.kind==='camera_observation'?'<p class="quiet">这是主动保存的摄像头画面，尚未判断猫咪活动；时间采用本机接收时间，来源时钟偏差待验证。</p>':''}<label class="field">更正活动类型<select id="kind">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${k===e.kind?'selected':''}>${v}</option>`).join('')}</select></label><button data-action="save-kind">保存类型更正</button><h3 class="event-history-heading">更正历史</h3><p class="quiet">${e.history.map(h=>`${esc(stamp(h.created_at))} · ${h.operation==='undo'?'撤回更正':'人工更正'} · v${h.version}`).join('<br>')||'尚无更正'}</p><button data-action="undo" ${!e.history.length||e.history.at(-1).operation==='undo'?'disabled':''}>撤回最近更正</button>`;
 const candidates=(e.camera_candidates||[]).length?eventDisclosure('event-cameras','同时间候选画面',e.camera_candidates.map(renderCandidate).join('')):'';
 const suspected=e.inference_candidates?.some(c=>c.state==='suspected_event');
 const inference=e.inference_candidates?.length?eventDisclosure('event-analysis',suspected?'画面分析候选 · 有疑似异常':'画面分析候选',`<p class="quiet">候选不确认身份或活动。${suspected?'存在疑似异常，请结合证据核实。':'自动检测尚未通过验证，不能据此判断发生了呕吐。'}</p>${e.inference_candidates.map(renderLocalization).join('')}`,suspected):'';
 $('#detail').innerHTML=`<article class="event-detail" data-event-id="${esc(e.id)}"><div class="dialog-head"><div><h2 id="dialog-title">${esc(title(e))}</h2><p class="event-meta">${esc(stamp(e.occurred_at))} · ${esc(eventLocation(e))}${duration}</p></div><button class="close" data-action="close" aria-label="关闭详情">×</button></div><div class="event-status"><span>${esc(truthLabels[e.truth])}</span><span>${e.partial_unknown?'身份待核对':'身份已归属'}</span>${e.mode==='fixture'?'<span>测试数据</span>':''}${e.kind==='camera_observation'?'<span>活动待核实</span>':''}</div><div id="event-evidence">${evidencePanel(e)}</div><section class="event-review"><div class="event-review-heading"><h3>核实记录</h3><small>这件事发生了吗？</small></div><div class="event-truth-actions"><button class="${e.truth==='rejected'?'':'primary'}" data-truth="confirmed" aria-pressed="${e.truth==='confirmed'}">${e.truth==='confirmed'?'已确认发生':'确认发生'}</button><button data-truth="${e.kind==='vomit'?'suspected':'reported'}" aria-pressed="${['reported','suspected'].includes(e.truth)}">暂不能判断</button><button class="event-reject" data-truth="rejected" aria-pressed="${e.truth==='rejected'}">${e.truth==='rejected'?'已否定':'否定记录'}</button></div>${e.kind==='vomit'&&e.truth!=='rejected'?`<div class="event-attention"><p class="quiet">${e.attention==='ended'?'本次关注已结束，不代表健康恢复。':'仍待关注；确认发生与结束关注是两件事。'}</p>${e.truth==='confirmed'?`<button data-attention="${e.attention==='ended'?'open':'ended'}">${e.attention==='ended'?'重新关注':'结束本次关注'}</button>`:''}</div>`:''}${eventIdentity(e)}</section>${candidates}${inference}${eventDisclosure('event-source','来源与更正历史',original)}<div id="save-error" class="error" role="alert"></div>${page==='review'?'<button class="event-skip" data-action="skip">跳过，稍后再看</button>':''}</article>`;
 $('#detail .close').focus();$('#detail').scrollTop=0;
 $('#detail').querySelectorAll('video,img').forEach(m=>m.addEventListener('error',()=>toast('证据加载失败；文字记录仍保留，请稍后重试。')));
}
async function correction(patch,undo=false){const btns=[...$('#detail').querySelectorAll('button')];const disabled=btns.map(b=>b.disabled);btns.forEach(b=>b.disabled=true);try{detail=await api(`/api/events/${detail.id}/${undo?'undo':'corrections'}`,{version:detail.version,patch});await refresh(false);renderEvent();toast('已保存，相关记录已更新');return true}catch(e){$('#save-error').textContent=e.message;btns.forEach((b,i)=>b.disabled=disabled[i]);return false}}
function editCat(id){const c=home.cats.find(c=>c.id===id)||{name:'',description:''};detail=null;formDirty=false;photoSession++;photoBusy=false;photoDraft=structuredClone(c.photos||{builtin:'default',version:0,avatar:null,references:[]});$('#detail').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${id?'编辑':'添加'}猫咪资料</h2><button class="close" data-action="close" aria-label="关闭编辑">×</button></div><form id="cat-form" data-id="${esc(id||'')}"><label class="field">名字<input name="name" required maxlength="30" value="${esc(c.name)}"></label><label class="field">外观区分说明 · 选填<textarea name="description" maxlength="200">${esc(c.description)}</textarea></label><section id="photo-editor"></section><p class="quiet">默认头像可以开始。参考照片独立用于人工核对，不训练模型。修改名字不会改变原有事件归属。</p><p id="save-error" class="error" role="alert"></p><div class="actions"><button class="primary" type="submit">保存资料</button><button type="button" data-action="close">取消</button>${id?'<button type="button" data-action="delete-cat">删除空档案</button>':''}</div></form>`;if(!$('#detail').open)$('#detail').showModal();renderPhotoEditor();$('#detail input').focus()}
function recordListRow(e,review){
 eventCache.set(e.id,e);
 return `<button class="record-list-row" data-event="${esc(e.id)}"><span class="event-thumb" data-thumbnail="${esc(e.id)}">${thumbnail(e)}</span><span class="row-copy"><strong>${esc(title(e))}</strong><small>${esc(clock(e.occurred_at))} · ${esc(eventLocation(e))}${e.mode==='fixture'?' · 测试数据':''}</small></span>${review?'<span class="record-row-action">认猫</span>':`<span class="tag">${e.truth==='rejected'?'已否定':e.partial_unknown?'待认猫':'已归属'}</span>`}<span class="record-row-chevron">${settingsIcon('chevron')}</span></button>`;
}
function showReviewHelp(){
 detail=null;formDirty=false;
 $('#detail').innerHTML='<div class="dialog-head"><h2 id="dialog-title">待认猫 · 核对说明</h2><button class="close" data-action="close" aria-label="关闭说明">×</button></div><p class="quiet">这里集中展示吃饭、喝水、如厕和疑似呕吐中，还没认全猫咪的记录。</p><p class="quiet">点开画面选择猫咪，可选择多只；认不清可以跳过。核对身份不会自动确认活动。</p>';
 $('#detail').showModal();
}
async function listPage(cat=null,review=false){
 const events=await api('/api/events?date='+encodeURIComponent(home.date)+(cat?'&cat='+encodeURIComponent(cat):''));
 page=review?'review':'history';
 const list=review?events.filter(e=>['food','water','litter','vomit'].includes(e.kind)&&e.partial_unknown&&e.truth!=='rejected'&&!skip.has(e.id)):events;
 const heading=review?'待认猫':cat?(home.cats.find(c=>c.id===cat)?.name||'猫咪')+'的日常':'全家历史';
 $('#content').innerHTML=`<section class="record-list-page"><div class="record-list-heading"><button class="record-list-back" data-page="home" aria-label="返回今日概览"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m14 6-6 6 6 6"></path></svg></button><div class="record-list-title"><h2 title="${esc(heading)}">${esc(heading)}</h2><span class="record-list-count" id="record-list-count">${list.length} 条</span></div>${review?'<button class="report-help record-list-help" data-action="review-help" aria-label="查看待认猫核对说明"><svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="9"></circle><path d="M12 11v6M12 7h.01"></path></svg></button>':''}<input class="record-list-date" id="history-day" type="date" aria-label="查看记录日期" value="${home.date}" data-cat="${esc(cat||'')}" data-review="${review}"></div>${!review?`<div class="record-list-filters"><select id="type-filter" aria-label="筛选活动"><option value="">全部活动</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><select id="identity-filter" aria-label="筛选身份"><option value="">全部身份</option><option value="unknown">待认猫</option></select></div>`:''}<div id="list">${list.length?list.map(e=>recordListRow(e,review)).join(''):`<p class="empty">${review?'这一天没有待认猫的记录。':'这一天还没有日常记录。'}</p>`}</div></section>`;
 observeThumbnails();nav();window.scrollTo(0,0);
 if(!review){
  const filter=()=>{
   const selected=list.filter(e=>(!$('#type-filter').value||e.kind===$('#type-filter').value)&&(!$('#identity-filter').value||e.partial_unknown));
   $('#record-list-count').textContent=selected.length+' 条';
   $('#list').innerHTML=selected.length?selected.map(e=>recordListRow(e,false)).join(''):'<p class="empty">暂无匹配记录。</p>';
   observeThumbnails();
  };
  $('#type-filter').onchange=filter;$('#identity-filter').onchange=filter;
 }
 return list;
}
async function nextReview(){const list=await listPage(null,true);if(list.length)await openEvent(list[0].id);else{$('#detail').close();toast('本次关键核对已结束')}}
async function capture(id,button){captureInProgress=true;button.disabled=true;button.textContent='正在保存画面…';try{const job=await api(`/api/sources/${id}/capture`,{});let result;for(let i=0;i<35;i++){await new Promise(r=>setTimeout(r,1000));result=await api('/api/capture-jobs/'+job.id);if(result.state==='failed')throw new Error(result.error);if(result.state==='completed')break}if(result?.state!=='completed')throw new Error('仍在保存，请稍后刷新查看，不必重复提交');await refresh();await openEvent(result.event_id);toast('画面已保存，活动尚未核实')}catch(e){toast(e.message)}finally{captureInProgress=false;button.disabled=false;button.textContent='保存一段当前画面'}}
document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b||b.disabled||profileSaving)return;try{if(b.dataset.avatarPreset){if(photoBusy)return;photoDraft.builtin=b.dataset.avatarPreset;photoDraft.avatar=null;formDirty=true;renderPhotoEditor();return}if(b.dataset.feedLocation)return await selectFeedLocation(b.dataset.feedLocation);if(b.dataset.reportView){reportView=b.dataset.reportView;renderHome();observeThumbnails();return}if(b.dataset.page){if(b.dataset.page==='home'){day='';page='home';await refresh()}else{page='settings';await refresh()}return}if(b.dataset.event)return await openEvent(b.dataset.event);if(b.dataset.editDevice)return editDevice(b.dataset.editDevice);if(b.dataset.cat)return await listPage(b.dataset.cat);if(b.dataset.edit)return editCat(b.dataset.edit);if(b.dataset.sourceRecording){b.disabled=true;await api(`/api/sources/${b.dataset.sourceRecording}/recording`,{recording:b.dataset.enable==='true'});await refresh(false);toast('来源设置已保存；后台正在切换状态');return}if(b.dataset.petkitImage){await ensureImage(detail,true);return}if(b.dataset.petkitHistory||b.dataset.petkitVideo){const source=b.dataset.petkitHistory||detail.source_id;const job=await api(`/api/sources/${source}/petkit-jobs`,{action:b.dataset.petkitHistory?'history':b.dataset.petkitVideo?'video':'image',argument:b.dataset.petkitHistory?home.date:detail.id});b.disabled=true;toast('只读任务已提交，正在读取');for(let i=0;i<60;i++){await new Promise(r=>setTimeout(r,2000));const result=await api('/api/petkit-jobs/'+job.id);if(result.state==='failed')throw new Error(result.error);if(result.state==='completed'){await refresh(false);if(detail)await openEvent(detail.id);toast('读取完成，已保存到本机');return}}toast('仍在读取，请稍后查看');b.disabled=false;return}if(b.dataset.candidate)return await candidateReview(b.dataset.candidate,b.dataset.association);if(b.dataset.capture)return await capture(b.dataset.capture,b);if(b.dataset.truth)return await correction({truth:b.dataset.truth});if(b.dataset.attention)return await correction({attention:b.dataset.attention});if(b.dataset.action==="device-status"){page="settings";await refresh();$("#settings-sources").open=true;return}if(b.dataset.action==="daily-help"){showDailyHelp();return}if(b.dataset.action==='review-help'){showReviewHelp();return}switch(b.dataset.action){case 'report-help':detail=null;$('#detail').innerHTML='<div class="dialog-head"><h2>吃喝日常 · 统计说明</h2><button class="close" data-action="close" aria-label="关闭说明">×</button></div><p class="quiet">根据所选日期的记录整理，不代表全天完整次数；— 表示尚无记录，不能推断猫咪没有吃喝。</p><p class="quiet">还没认出是哪只猫的记录，暂不计入单只猫咪；添粮不等于吃饭，饮水机出水工作不等于喝水。</p>';formDirty=false;$('#detail').showModal();break;case 'close':if(profileSaving)break;if(!formDirty||confirm('放弃尚未保存的修改？')){photoSession++;$('#detail').close();formDirty=false}break;case 'add-cat':editCat();break;case 'create-family':b.disabled=true;for(const [name,builtin] of [['汤圆','a'],['飞饼','b'],['话唠','c']])if(!home.cats.some(c=>c.name===name))await api('/api/cat-profiles',{name,description:'',photos:{builtin,version:0,avatar:null,references:[]}});await refresh();break;case 'storage':storageLoading=true;if(page==='settings')renderSettings();try{storageSnapshot={...await api('/api/storage'),checked_at:new Date().toISOString()}}finally{storageLoading=false;if(page==='settings')renderSettings()}break;case 'toggle':await api('/api/runtime',{recording:!home.runtime.recording});await refresh();break;case 'more':{const scroll=window.scrollY,location=feedLocation,request=homeRequest;const more=await api(dailyFeedQuery({date:home.date,cursor}));if(location!==feedLocation||request!==homeRequest||page!=='home')return;const ids=new Set(feed.map(e=>e.id));feed.push(...more.events.filter(e=>!ids.has(e.id)));cursor=more.next_cursor;const strip=$('#daily-location-filters').scrollLeft;renderHome();$('#daily-location-filters').scrollLeft=strip;observeThumbnails();window.scrollTo(0,scroll);break}case 'history':await listPage();break;case 'review':skip=new Set();await nextReview();break;case 'skip':skip.add(detail.id);await nextReview();break;case 'undo':await correction(null,true);break;case 'save-kind':await correction({kind:$('#kind').value});break;case 'delete-cat':if(confirm('只允许删除没有任何事件关联的档案。确定删除？')){await api(`/api/cats/${$('#cat-form').dataset.id}/delete`,{confirmed:true});$('#detail').close();await refresh()}break}}catch(e){b.disabled=false;toast(e.message)}});
document.addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.target;if(form.id==='identity-form'){const ok=await correction({participants:[...form.querySelectorAll('[name=participant]:checked')].map(x=>x.value),partial_unknown:form.elements.unknown.checked});if(ok&&page==='review')await nextReview()}else if(form.id==='cat-form'){const b=form.querySelector('[type=submit]');const controls=[...form.elements],previousDisabled=controls.map(x=>x.disabled);b.disabled=true;try{if(photoBusy)throw new Error('图片处理中，请稍候');profileSaving=true;controls.forEach(x=>x.disabled=true);const saved=await api('/api/cat-profiles',{id:form.dataset.id||undefined,name:form.elements.name.value,description:form.elements.description.value,photos:photoDraft});formDirty=false;$('#detail').close();await refresh();toast(saved.duplicate_name?'已保存，注意家里有同名猫咪。':'猫咪资料已保存')}catch(e){$('#save-error').textContent=e.message}finally{profileSaving=false;controls.forEach((x,i)=>x.disabled=previousDisabled[i]);b.disabled=photoBusy}}});
document.addEventListener('change',async ev=>{if(ev.target.id==='day'){day=ev.target.value;await refresh()}if(ev.target.id==='history-day'){day=ev.target.value;home=await api('/api/home?date='+encodeURIComponent(day));await listPage(ev.target.dataset.cat||null,ev.target.dataset.review==='true')}});
$('#detail').addEventListener('input',()=>formDirty=true);$('#detail').addEventListener('cancel',e=>{if(profileSaving||(formDirty&&!confirm('放弃尚未保存的修改？')))e.preventDefault();else formDirty=false});$('#detail').addEventListener('close',()=>{photoSession++;const v=$('#detail video');if(v)v.pause()});
refresh();setInterval(()=>{if((page==='home'||page==='settings')&&!$('#detail').open&&!captureInProgress)refresh(false)},5000);

function photoSrc(p){return p.url||`data:${p.mime};base64,${p.data}`}
function renderPhotoEditor(){
 const root=$('#photo-editor');if(!root)return;
 root.innerHTML=`<h3>头像</h3><div class="avatar-preview"><img id="avatar-preview" src="${esc(photoDraft.avatar?photoSrc(photoDraft.avatar):avatarUrl({photos:photoDraft}))}" alt="头像裁剪预览"></div><div class="avatar-presets" role="group" aria-label="预设猫咪头像">${[['a','金渐层'],['b','浅金渐层'],['c','狸花猫']].map(([value,label])=>`<button type="button" data-avatar-preset="${value}" aria-pressed="${!photoDraft.avatar&&(photoDraft.builtin===value||(value==='a'&&photoDraft.builtin==='default'))}" ${photoBusy?'disabled':''}><img src="/assets/cat-${value}.png" alt=""><span>${label}</span></button>`).join('')}</div><label class="field avatar-builtin-legacy" hidden>内置头像<select id="avatar-builtin">${['default','a','b','c'].map(v=>`<option value="${v}" ${photoDraft.builtin===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">上传头像<input id="avatar-upload" type="file" accept="image/jpeg,image/png,image/webp" ${photoBusy?'disabled':''}></label>${photoDraft.avatar?.data?`<label class="field">居中裁剪缩放<input id="avatar-zoom" type="range" min="1" max="3" step="0.05" value="${photoDraft.avatar.zoom||1}"></label>`:''}<h3>参考照片 · ${photoDraft.references.length}/3</h3><div class="reference-grid">${photoDraft.references.map((p,i)=>`<div><div class="reference-preview ${p.crop?'cropped':''}"><img data-reference-preview="${i}" src="${esc(photoSrc(p))}" alt="参考照片${i+1}" style="transform:scale(${p.crop?(p.zoom||1):1})"></div>${p.data?`<label>居中裁剪<input type="checkbox" data-reference-crop="${i}" ${p.crop?'checked':''}></label>${p.crop?`<label>缩放<input type="range" data-reference-zoom="${i}" min="1" max="3" step="0.05" value="${p.zoom||1}"></label>`:''}`:''}<button type="button" data-remove-reference="${i}">移除</button></div>`).join('')}</div><label class="field">添加参考照片（最多3张）<input id="reference-upload" type="file" multiple accept="image/jpeg,image/png,image/webp" ${photoBusy?'disabled':''}></label><p class="quiet">JPEG / PNG / WebP，每张最多8MB。${photoBusy?'图片处理中…':''}</p>`;
 if(photoDraft.avatar?.data)updateCropPreview();
}
function updateCropPreview(){const img=$('#avatar-preview');if(img)img.style.transform=`scale(${photoDraft.avatar?.zoom||1})`}
async function readPhoto(file){
 if(!['image/jpeg','image/png','image/webp'].includes(file.type)||!file.size||file.size>8*1024*1024)throw new Error('请选择8MB以内的JPEG、PNG或WebP图片');
 const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(new Error('图片读取失败'));r.readAsDataURL(file)});
 const value={mime:file.type,data,zoom:1};
 await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>img.width*img.height>20000000?reject(new Error('图片像素过大')):resolve();img.onerror=()=>reject(new Error('图片解码失败'));img.src=photoSrc(value)});return value;
}
document.addEventListener('change',async ev=>{
 if(ev.target.dataset.referenceCrop!==undefined){photoDraft.references[Number(ev.target.dataset.referenceCrop)].crop=ev.target.checked;formDirty=true;renderPhotoEditor()}
 if(ev.target.id==='avatar-builtin'){photoDraft.builtin=ev.target.value;photoDraft.avatar=null;formDirty=true;renderPhotoEditor()}
 if(!['avatar-upload','reference-upload'].includes(ev.target.id))return;
 const session=photoSession,role=ev.target.id,files=[...ev.target.files];if(!files.length)return;
 photoBusy=true;formDirty=true;$('#cat-form [type=submit]').disabled=true;renderPhotoEditor();
 try{if(role==='reference-upload'&&photoDraft.references.length+files.length>3)throw new Error('参考照片最多3张');const values=await Promise.all(files.map(readPhoto));if(session!==photoSession)return;if(role==='avatar-upload')photoDraft.avatar=values[0];else photoDraft.references.push(...values);$('#save-error').textContent=''}catch(e){if(session===photoSession)$('#save-error').textContent=e.message}finally{if(session===photoSession){photoBusy=false;renderPhotoEditor();$('#cat-form [type=submit]').disabled=false}}
});
document.addEventListener('input',ev=>{if(ev.target.dataset.referenceZoom!==undefined){const i=Number(ev.target.dataset.referenceZoom);photoDraft.references[i].zoom=Number(ev.target.value);const img=document.querySelector(`[data-reference-preview="${i}"]`);if(img)img.style.transform=`scale(${ev.target.value})`}if(ev.target.id==='avatar-zoom'){photoDraft.avatar.zoom=Number(ev.target.value);updateCropPreview()}});
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-remove-reference]');if(b&&!photoBusy){photoDraft.references.splice(Number(b.dataset.removeReference),1);formDirty=true;renderPhotoEditor()}});
